import{_ as e}from"./chunks/more.BA9dr6o4.js";import{_ as t,c as r,o,a2 as i}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"更多比较方式","description":"比较图片与压缩包、把差异导出成图片，以及调整外观与语言。","frontmatter":{"title":"更多比较方式","description":"比较图片与压缩包、把差异导出成图片，以及调整外观与语言。"},"headers":[],"relativePath":"zh-CN/guide/more.md","filePath":"zh-CN/guide/more.md","lastUpdated":1793948370000}'),l={name:"zh-CN/guide/more.md"};function s(n,a,h,d,p,c){return o(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="更多比较方式" tabindex="-1">更多比较方式 <a class="header-anchor" href="#更多比较方式" aria-label="Permalink to &quot;更多比较方式&quot;">​</a></h1><p>文字只是其中一半。qDiff 用同样的「并排」思路，也能打开别的内容。</p><img src="'+e+'" alt="两张图片并排比较" class="guide-shot"><h2 id="图片" tabindex="-1">图片 <a class="header-anchor" href="#图片" aria-label="Permalink to &quot;图片&quot;">​</a></h2><p>把两张图并排放着慢慢看，或者叠在一起，直接看出哪里不一样 —— 设计改版、 几乎一模一样的照片，都很合适。</p><h2 id="压缩包" tabindex="-1">压缩包 <a class="header-anchor" href="#压缩包" aria-label="Permalink to &quot;压缩包&quot;">​</a></h2><p>.zip / .tar 可以直接打开，像文件夹一样比。不用解压，也不用事后清理临时文件。</p><h2 id="不是纯文本的文件" tabindex="-1">不是纯文本的文件 <a class="header-anchor" href="#不是纯文本的文件" aria-label="Permalink to &quot;不是纯文本的文件&quot;">​</a></h2><p>两个文件看起来一样、用起来却不同时，qDiff 还能细到最小的差别，把普通文字 视图看不出来的变化也找出来。</p><h2 id="把一次比较存成图片" tabindex="-1">把一次比较存成图片 <a class="header-anchor" href="#把一次比较存成图片" aria-label="Permalink to &quot;把一次比较存成图片&quot;">​</a></h2><p>选中一处改动，导出成一张干净的双栏图片，直接贴进聊天、文档或评审里。 导出的图片不会加任何标记。</p><h2 id="按你的习惯来" tabindex="-1">按你的习惯来 <a class="header-anchor" href="#按你的习惯来" aria-label="Permalink to &quot;按你的习惯来&quot;">​</a></h2><ul><li><strong>外观</strong> —— 浅色与深色，可以跟随 Mac，也可以自己指定。</li><li><strong>语言</strong> —— 简体中文、繁体中文、英文等多种界面语言。</li><li><strong>字体与快捷键</strong> —— 读着舒服，常用的操作也能用键盘完成。</li><li><strong>最近比较</strong> —— 昨天看过的内容，在欢迎页一点就回来。</li></ul><p>以上全部包含在免费版里。</p><p>还有疑问？<a href="./faq.html">看看常见问题</a>。</p>',15)])])}const f=t(l,[["render",s]]);export{u as __pageData,f as default};
